-- seed.sql: referensi, pengaturan, master tarif asli, akun pengguna, dan satu dosen contoh. Data dosen/kelas/BKD/tugas tambahan sungguhan datang dari sinkronisasi SISTER.
-- Dijalankan sekali sesudah schema.sql. Tarif = master tarif asli dari rekap-data-tarif-honor.xlsx.
BEGIN;



-- Semester yang dikenal. Semester lain dibuat otomatis oleh perintah sinkron:sister bila belum ada.


-- Pajak: dikonfirmasi Keuangan (honor menurut golongan). Golongan dosen diturunkan dari jabatan fungsional (pemetaan di bawah).

-- Golongan menurut jabatan fungsional (golongan ruang PNS yang lazim untuk jabatan itu). Tenaga Pengajar sengaja TIDAK ada: menunggu keputusan Keuangan.

-- Pola kode kelas SISTER -> mitra kerja sama. Tiap kode didaftarkan sebagai awalan DAN akhiran (mis. 6AMSU, JGU7A, ABDK, ARPL, ASBI).
-- Pemetaan sementara, tunggu konfirmasi: BDK=BADAK, RPL=RESD (foto Master Tarif), SBI=HOLCIM (nama kelas tarif HOLCIM memuat "PT SBI").
-- FORMOSA belum diketahui kodenya. Kelas reguler hanya berbentuk [kode prodi][semester][huruf kelas], mis. TI5A; kelas lain yang belum cocok pola tampil di view v_kelas_belum_dikenali.

  ('akhiran', 'SBI', 'HOLCIM'), ('awalan', 'SBI', 'HOLCIM');

-- Prodi usulan (PERLU DIKONFIRMASI jurusan dan jenjangnya). Pencocokan dengan data SISTER memakai nama prodi saja. Prodi SISTER yang belum ada di sini: lihat view v_prodi_belum_dikenal.
SELECT v.n, v.j, jr.id_jurusan FROM (VALUES
  ('Konstruksi Gedung','D3','Teknik Sipil'), ('Konstruksi Sipil','D3','Teknik Sipil'), ('Teknik Perancangan Jalan dan Jembatan','D4','Teknik Sipil'),
  ('Teknik Mesin','D3','Teknik Mesin'), ('Teknik Konversi Energi','D3','Teknik Mesin'),
  ('Elektronika Industri','D3','Teknik Elektro'), ('Telekomunikasi','D3','Teknik Elektro'), ('Teknik Elektronika Industri','D4','Teknik Elektro'),
  ('Akuntansi','D3','Akuntansi'), ('Keuangan dan Perbankan','D3','Akuntansi'), ('Manajemen Keuangan','D3','Akuntansi'),
  ('Bahasa Inggris untuk Komunikasi Bisnis dan Profesional','D3','Administrasi Niaga'), ('Usaha Jasa Konvensi, Perjalanan Insentif dan Pameran (MICE)','D4','Administrasi Niaga'),
  ('Desain Grafis','D3','Teknik Grafika dan Penerbitan'), ('Teknologi Industri Cetak Kemasan','D4','Teknik Grafika dan Penerbitan'),
  ('Teknik Informatika','D4','Teknik Informatika dan Komputer'), ('Teknik Multimedia dan Jaringan','D4','Teknik Informatika dan Komputer'),
  ('Teknik Komputer dan Jaringan','D3','Teknik Informatika dan Komputer')
) AS v(n,j,jur) JOIN jurusan jr ON jr.nama_jurusan = v.jur
ON CONFLICT DO NOTHING;

-- Pemetaan tugas tambahan -> kelompok SKS wajib: USULAN (Perdir 11/2025 Lampiran II), perlu dikonfirmasi. Jenis lain dibiarkan kosong: dihitung DS + catatan, daftar lengkap di v_tugas_belum_dipetakan.
ON CONFLICT DO NOTHING;

-- Master tarif ASLI (rekap-data-tarif-honor.xlsx / INTEGRATIA MASTERING): 279 baris, Reguler dan Kerja Sama per mitra, program studi, dan jabatan.
-- Sumber tidak memuat tanggal mulai, jadi 2025-01-01 dipakai; tanggal kedaluwarsa dari sumber. Baris cacat tetap dimasukkan tetapi aktif = false (lihat kolom catatan).

-- ==== Akun dan data contoh (untuk mencoba semua halaman tanpa menunggu SISTER) ====
-- Satu dosen contoh ("Dosen B", id dummy, bukan dari SISTER) dengan 12 kelas, 2 perhitungan, dan 5 kegiatan non-pengajaran, dipegang oleh akun demo dan dosen.b.
-- Data SISTER sungguhan masuk lewat sinkronisasi dan tidak bercampur dengan dosen ini.
-- Akun: demo (login lokal, semua peran; kata sandi diatur dengan `php artisan integratia:atur-password demo`), dosen.b (dosen + pimpinan),
-- pimpinan, keuangan, admin.input, admin.super (login SSO: harus terdaftar di tabel ini dengan username/email SSO yang sama).

COMMIT;
-- Tarif honor non-pengajaran (SBM Internal PNJ 23/2026)
ON CONFLICT (kode) DO NOTHING;

